// HasAPIKey applies the HasEdge predicate on the "api_key" edge.
func HasAPIKey() predicate.APIKeyRouteConfigOutbox {
	return predicate.APIKeyRouteConfigOutbox(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.M2O, true, APIKeyTable, APIKeyColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasAPIKeyWith applies the HasEdge predicate on the "api_key" edge with a given conditions (other predicates).
func HasAPIKeyWith(preds ...predicate.APIKey) predicate.APIKeyRouteConfigOutbox {
	return predicate.APIKeyRouteConfigOutbox(func(s *sql.Selector) {
		step := newAPIKeyStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

// And groups predicates with the AND operator between them.
func And(predicates ...predicate.APIKeyRouteConfigOutbox) predicate.APIKeyRouteConfigOutbox {
	return predicate.APIKeyRouteConfigOutbox(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.APIKeyRouteConfigOutbox) predicate.APIKeyRouteConfigOutbox {
	return predicate.APIKeyRouteConfigOutbox(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.APIKeyRouteConfigOutbox) predicate.APIKeyRouteConfigOutbox {
	return predicate.APIKeyRouteConfigOutbox(sql.NotPredicates(p))
}
